from .base_wrapper import ListAbstractionsWrapper
from taf.config.testline.ue import Airphone


class _AirphoneWrapper(ListAbstractionsWrapper):
    """
    All redirections for airphone are contained inside this wrapper's properties
    """
    def __init__(self, tl_config):
        super(_AirphoneWrapper, self).__init__(tl_config)
        self.airphone = self.get_instance(Airphone, self.tl_config.ues)

    @property
    def addr(self):
        return self.airphone.egate.addr

    @property
    def username(self):
        return self.airphone.egate.username

    @property
    def password(self):
        return self.airphone.egate.password
